/* userMapper.xml#insertUser */
SELECT nextval('user_tb_user_id_seq')
INSERT INTO USER_TB (user_id, name, email, password, phone_number, birth, create_date, uuid, account_type, status) VALUES (#{userId}, #{name}, #{email}, #{password}, #{phoneNumber}, #{birth}, #{createDate}, #{uuid}, #{accountType}, #{status})

mapper.update:
UPDATE
    user_tb
SET
    status = #{status}
WHERE
    uuid = #{uuid}

mapper.select:
SELECT EXISTS(
    SELECT user_id
    FROM USER_TB
    WHERE
        email = #{email}
    OR
        phone_number = #{phoneNumber}
)

SELECT user_id, name, email, account_type, uuid
FROM user_tb
WHERE uuid = #{uuid}

/** selectUserByEmail */
SELECT email, password, account_type, status, uuid
FROM user_tb
WHERE email = #{email}
